    <>
      <a className="skip" href="#main">Skip to content</a>
      <Nav />
      <main id="main">
        <Story joined={joined} onJoined={setJoined} />
        <FightSection />
        <Method />
        <Live />
        <Final joined={joined} onJoined={setJoined} />
      </main>
      <Footer />
    </>
  );
}

